import{_ as o,c as t,o as n,ag as a}from"./chunks/framework.CB_NIqHd.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/EngX_Quality/How_would_you_onboard_new_people_on_a_project,_What_kind_of_documentation,_style_guide_would_you_use.md","filePath":"senior_growth/EngX_Quality/How_would_you_onboard_new_people_on_a_project,_What_kind_of_documentation,_style_guide_would_you_use.md"}'),r={name:"senior_growth/EngX_Quality/How_would_you_onboard_new_people_on_a_project,_What_kind_of_documentation,_style_guide_would_you_use.md"};function i(s,e,l,d,c,u){return n(),t("div",null,[...e[0]||(e[0]=[a('<h2 id="how-would-you-onboard-new-people-on-a-project-what-kind-of-documentation-style-guide-would-you-use" tabindex="-1">How would you onboard new people on a project? What kind of documentation/style guide would you use? <a class="header-anchor" href="#how-would-you-onboard-new-people-on-a-project-what-kind-of-documentation-style-guide-would-you-use" aria-label="Permalink to “How would you onboard new people on a project? What kind of documentation/style guide would you use?”">​</a></h2><p>Onboarding new team members effectively is crucial for productivity and team cohesion. A well-structured onboarding process ensures that new members quickly understand the project, tools, and best practices, enabling them to contribute efficiently. Here&#39;s how to approach it:</p><hr><h2 id="_1-prepare-for-onboarding" tabindex="-1"><strong>1. Prepare for Onboarding</strong> <a class="header-anchor" href="#_1-prepare-for-onboarding" aria-label="Permalink to “1. Prepare for Onboarding”">​</a></h2><h3 id="key-steps" tabindex="-1"><strong>Key Steps:</strong> <a class="header-anchor" href="#key-steps" aria-label="Permalink to “Key Steps:”">​</a></h3><ol><li><strong>Identify Goals</strong>: Clarify what the new hire should accomplish in their first days/weeks.</li><li><strong>Set Up Accounts</strong>: Provide access to tools, repositories, environments, and communication channels in advance.</li><li><strong>Assign a Mentor/Buddy</strong>: Pair the new hire with an experienced team member for guidance.</li></ol><hr><h2 id="_2-provide-a-comprehensive-overview" tabindex="-1"><strong>2. Provide a Comprehensive Overview</strong> <a class="header-anchor" href="#_2-provide-a-comprehensive-overview" aria-label="Permalink to “2. Provide a Comprehensive Overview”">​</a></h2><h3 id="project-overview" tabindex="-1"><strong>Project Overview</strong> <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project Overview”">​</a></h3><ul><li><strong>Mission and Vision</strong>: Explain the project’s purpose, goals, and value.</li><li><strong>Current Status</strong>: Share details about ongoing features, challenges, and future plans.</li><li><strong>Architecture Diagram</strong>: Visualize the system’s architecture, components, and data flow.</li></ul><hr><h2 id="_3-documentation-for-onboarding" tabindex="-1"><strong>3. Documentation for Onboarding</strong> <a class="header-anchor" href="#_3-documentation-for-onboarding" aria-label="Permalink to “3. Documentation for Onboarding”">​</a></h2><h3 id="types-of-documentation" tabindex="-1"><strong>Types of Documentation</strong> <a class="header-anchor" href="#types-of-documentation" aria-label="Permalink to “Types of Documentation”">​</a></h3><ol><li><strong>Project Documentation</strong><ul><li><strong>README File</strong>: Concise, high-level introduction to the project.</li><li><strong>Getting Started Guide</strong>: Step-by-step instructions to set up the local development environment.</li><li><strong>Architecture Documentation</strong>: Includes diagrams, data flows, and high-level design decisions.</li><li><strong>API Documentation</strong>: Endpoint descriptions, data schemas, and example requests/responses.</li><li><strong>Key Features</strong>: Highlight core functionalities and their purpose.</li></ul></li><li><strong>Process Documentation</strong><ul><li><strong>Team Roles and Responsibilities</strong>: Clarify who owns what in the project.</li><li><strong>Development Workflow</strong>: Explain branching strategies, code review processes, CI/CD pipelines, and deployment procedures.</li><li><strong>Ticket Workflow</strong>: Describe how issues or stories are created, prioritized, and tracked.</li></ul></li><li><strong>Technical Documentation</strong><ul><li><strong>Codebase Walkthrough</strong>: Guide through folder structures, naming conventions, and critical files.</li><li><strong>Tech Stack Overview</strong>: Explain the technologies, libraries, and frameworks used, including why they were chosen.</li><li><strong>Error Handling</strong>: Document common issues and their solutions.</li><li><strong>Testing Guidelines</strong>: Describe unit, integration, and end-to-end testing processes and tools.</li></ul></li><li><strong>Style Guide</strong><ul><li><strong>Code Style</strong>: Follow a standard like <strong>Airbnb for JavaScript/React</strong> or use a tool like ESLint/Prettier.</li><li><strong>Design Guidelines</strong>: Use a design system (e.g., Material Design, Tailwind) and maintain a UI component library.</li><li><strong>Documentation Style</strong>: Set standards for writing clear and concise comments, commit messages, and documentation.</li></ul></li><li><strong>FAQs and Knowledge Base</strong><ul><li><strong>Common Questions</strong>: Address frequently asked questions about the project, tools, or setup.</li><li><strong>Troubleshooting Guide</strong>: Help new members resolve common errors.</li></ul></li></ol><hr><h2 id="_4-leverage-tools" tabindex="-1"><strong>4. Leverage Tools</strong> <a class="header-anchor" href="#_4-leverage-tools" aria-label="Permalink to “4. Leverage Tools”">​</a></h2><h3 id="documentation-tools" tabindex="-1"><strong>Documentation Tools</strong> <a class="header-anchor" href="#documentation-tools" aria-label="Permalink to “Documentation Tools”">​</a></h3><ul><li><strong>Internal Wikis</strong>: Confluence, Notion, or GitHub Wiki.</li><li><strong>Code Comments</strong>: Inline comments for critical parts of the codebase.</li><li><strong>Diagrams</strong>: Tools like Lucidchart, Miro, or Mermaid.js for architectural diagrams.</li></ul><h3 id="style-guides-and-linters" tabindex="-1"><strong>Style Guides and Linters</strong> <a class="header-anchor" href="#style-guides-and-linters" aria-label="Permalink to “Style Guides and Linters”">​</a></h3><ul><li><strong>Code Linters</strong>: ESLint, Stylelint, or RuboCop to enforce standards automatically.</li><li><strong>Prettier</strong>: For consistent formatting.</li><li><strong>UI Style Guide</strong>: Storybook for React/Vue components.</li></ul><hr><h2 id="_5-onboarding-roadmap" tabindex="-1"><strong>5. Onboarding Roadmap</strong> <a class="header-anchor" href="#_5-onboarding-roadmap" aria-label="Permalink to “5. Onboarding Roadmap”">​</a></h2><h3 id="day-1–3" tabindex="-1"><strong>Day 1–3</strong> <a class="header-anchor" href="#day-1–3" aria-label="Permalink to “Day 1–3”">​</a></h3><ul><li>Introduce the team and provide a project overview.</li><li>Set up development environment and tools.</li><li>Walk through the documentation and key workflows.</li></ul><h3 id="week-1–2" tabindex="-1"><strong>Week 1–2</strong> <a class="header-anchor" href="#week-1–2" aria-label="Permalink to “Week 1–2”">​</a></h3><ul><li>Complete hands-on tasks (e.g., fixing a small bug or implementing a minor feature).</li><li>Attend team meetings to understand collaboration and decision-making processes.</li><li>Conduct codebase walkthroughs with a mentor.</li></ul><h3 id="month-1" tabindex="-1"><strong>Month 1</strong> <a class="header-anchor" href="#month-1" aria-label="Permalink to “Month 1”">​</a></h3><ul><li>Take ownership of a feature or module.</li><li>Participate in code reviews and deploy code.</li><li>Provide feedback on the onboarding process.</li></ul><hr><h2 id="_6-continuous-learning-and-feedback" tabindex="-1"><strong>6. Continuous Learning and Feedback</strong> <a class="header-anchor" href="#_6-continuous-learning-and-feedback" aria-label="Permalink to “6. Continuous Learning and Feedback”">​</a></h2><ul><li><strong>Learning</strong>: Encourage participation in workshops, code reviews, and pairing sessions.</li><li><strong>Feedback</strong>: Regularly check in with the new hire to identify blockers and improve the onboarding process.</li></ul><h2 id="read-a-decision-record-then-test-its-boundary" tabindex="-1">Read a decision record, then test its boundary <a class="header-anchor" href="#read-a-decision-record-then-test-its-boundary" aria-label="Permalink to “Read a decision record, then test its boundary”">​</a></h2><p>Start with <a href="./../React/application_struvture.html#a-proposed-decision-with-an-executable-boundary">ADR-STUDY-01: UI uses an application port</a>. Its status is proposed for a learner fixture, not an adopted decision in a real employer&#39;s project. Context: direct UI imports of concrete infrastructure make adapter changes leak into UI tests. Forces: a small understandable feature, test substitution, dependency ownership and a migration cost that must stay reviewable. Alternatives are a direct import for a tiny isolated script, a feature port/composition boundary, or broader dependency-graph enforcement when actual cycles/bypasses justify it.</p><p>Decision: try the feature port for one caller. Consequences: one explicit contract and composition owner; easier substitution if the contract is stable; added indirection and possible barrel/alias bypass if enforcement is only a string rule. Validation: the ESLint fixture rejects known direct infrastructure spellings and accepts the application port. It cannot establish a whole dependency graph or server permission boundary. Revisit on a real exception/cycle or when migration cost exceeds the observed value; accept/supersede the record through the team&#39;s review process rather than silently changing its meaning.</p><p><strong>Onboarding exercise:</strong> locate the UI → application port → adapter path, explain who constructs the adapter and run both positive and negative boundary cases. Propose one justified exception, record the risk/owner/expiry and explain whether the rule or architecture should change. Then trace the title helper&#39;s <a href="./How_would_you_approach_significant_refactoring.html#estimate-uncertainty-and-make-the-debt-decision-reviewable">incremental migration and estimate</a>. Acceptance: a new reader can identify the decision, alternatives, forces, consequences, current status, evidence and revisit trigger without relying on undocumented chat history. The record is worked learning material; actual teammate onboarding, decision adoption and measured communication outcomes remain learner practice.</p><p>A decision log complements a current architecture diagram: the diagram shows today&#39;s structure, while the record explains why a choice was made under then-known constraints. Keep accepted records stable and add a superseding record with links when the choice changes. Avoid invented personal experience or “all decisions must be permanent” claims. For a record format see <a href="https://adr.github.io/madr/" target="_blank" rel="noreferrer">Markdown Architectural Decision Records</a>; the schema is an alternative to an existing team template, not a new mandatory tool.</p>',36)])])}const p=o(r,[["render",i]]);export{g as __pageData,p as default};
